async function generateResponse(inputText) {
  const input = transformers.encodeText(inputText);
  const output = await window.model.generate(input, {
    max_length: 200,
    num_beams: 4,
  });
  const responseText = transformers.decodeText(output[0]);
  return responseText;
}

// Function to send a message
async function sendMessage() {
  const inputText = userInput.value.trim();
  if (inputText !== '') {
    // Add the user's message to the chat log
    const userMessageElement = document.createElement('li');
    userMessageElement.textContent = `User: ${inputText}`;
