**Chess Program in Python**
=========================

This is a basic implementation of a chess program in Python. It allows you to play against yourself. The program uses a simple text-based interface to display the board and accept moves.

**Code**
```python
class Piece:
    def __init__(self, color, x, y):
        self.color = color
        self.x = x
        self.y = y

    def __str__(self):
        return f"{self.color} {self.__class__.__name__}"


class King(Piece):
    def __init__(self, color, x, y):
        super().__init__(color, x, y)


class Queen(Piece):
    def __init__(self, color, x, y):
        super().__init__(color, x, y)


class Rook(Piece):
    def __init__(self, color, x, y):
        super().__init__(color, x, y)


class Bishop(Piece):
    def __init__(self, color, x, y):
        super().__init__(color, x, y)


class Knight(Piece):
    def __init__(self, color, x, y):
        super().__init__(color, x, y)


class Pawn(Piece):
    def __init__(self, color, x, y):
        super().__init__(color, x, y)


class ChessBoard:
    def __init__(self):
        self.board = self.initialize_board()

    def initialize_board(self):
        # Initialize an empty board
        board = [[None for _ in range(8)] for _ in range(8)]

        # Place pawns
        for i in range(8):
            board[1][i] = Pawn("white", i, 1)
            board[6][i] = Pawn("black", i, 6)

        # Place rooks
        board[0][0] = Rook("white", 0, 0)
        board[0][7] = Rook("white", 7, 0)
        board[7][0] = Rook("black", 0, 7)
        board[7][7] = Rook("black", 7, 7)

        # Place knights
        board[0][1] = Knight("white", 1, 0)
        board[0][6] = Knight("white", 6, 0)
        board[7][1] = Knight("black", 1, 7)
        board[7][6] = Knight("black", 6, 7)

        # Place bishops
        board[0][2] = Bishop("white", 2, 0)
        board[0][5] = Bishop("white", 5, 0)
        board[7][2] = Bishop("black", 2, 7)
        board[7][5] = Bishop("black", 5, 7)

        # Place queens
        board[0][3] = Queen("white", 3, 0)
        board[7][3] = Queen("black", 3, 7)

        # Place kings
        board[0][4] = King("white", 4, 0)
        board[7][4] = King("black", 4, 7)

        return board

    def print_board(self):
        print("  a b c d e f g h")
        for i in range(8):
            print(i + 1, end=" ")
            for j in range(8):
                if self.board[i][j] is None:
                    print("-", end=" ")
                else:
                    piece = self.board[i][j]
                    if isinstance(piece, King):
                        print("K" if piece.color == "white" else "k", end=" ")
                    elif isinstance(piece, Queen):
                        print("Q" if piece.color == "white" else "q", end=" ")
                    elif isinstance(piece, Rook):
                        print("R" if piece.color == "white" else "r", end=" ")
                    elif isinstance(piece, Bishop):
                        print("B" if piece.color == "white" else "b", end=" ")
                    elif isinstance(piece, Knight):
                        print("N" if piece.color == "white" else "n", end=" ")
                    elif isinstance(piece, Pawn):
                        print("P" if piece.color == "white" else "p", end=" ")
            print()

    def move_piece(self, x1, y1, x2, y2):
        if self.board[y1][x1] is None:
            print("There is no piece at the specified position.")
            return
        piece = self.board[y1][x1]
        self.board[y1][x1] = None
        self.board[y2][x2] = piece
        piece.x = x2
        piece.y = y2


def main():
    board = ChessBoard()
    while True:
        board.print_board()
        x1 = ord(input("Enter the x-coordinate of the piece to move (a-h): ")) - 97
        y1 = int(input("Enter the y-coordinate of the piece to move (1-8): ")) - 1
        x2 = ord(input("Enter the x-coordinate of the destination (a-h): ")) - 97
        y2 = int(input("Enter the y-coordinate of the destination (1-8): ")) - 1
        board.move_piece(x1, y1, x2, y2)


if __name__ == "__main__":
    main()
```
**How to Run the Program**
1. Save the code in a file named `chess.py`.
2. Open a terminal and navigate to the directory where you saved the file.
3. Run the program using Python by typing `python chess.py`.
4. Follow the prompts to move pieces around the board.

Note: This is a very basic implementation of a chess program. It does not include any validation for moves, so you can move pieces to any position on the board, even if it's not a valid move. It also does not include any check for checkmate or stalemate. You may want to add these features yourself as an exercise.

