Here's an example of blocking read interrupted by a signal with EINTR handling in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Global variable to track number of interruptions
int interrupted_count = 0;

// Handler function for the signal
void signal_handler(int signum) {
    interrupted_count++;
    printf("Received signal %d, interrupted count: %d\n", signum, interrupted_count);
}

int main() {
    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open a file for reading
    FILE *file = fopen("example.txt", "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    char buffer[1024];

    while (1) {
        // Perform a blocking read
        ssize_t bytes_read = fread(buffer, 1, 1024, file);
        if (bytes_read == 0) {
            // End of file
            break;
        }

        // Print the read data
        printf("%.*s", (int) bytes_read, buffer);

        // Check if the read was interrupted by a signal
        if (ferror(file) && errno == EINTR) {
            // Clear the error flag
            clearerr(file);
            printf("Read interrupted by signal, retrying...\n");
            // You can also sleep for a short duration before retrying
            // usleep(100000); // sleep for 0.1 seconds
        }
    }

    // Close the file
    fclose(file);

    return 0;
}
```

However, the above example does not directly apply to the standard C fread function, because the C standard does not have anything like the POSIX EINTR error. EINTR is typically seen when working with system calls like `read(2)` directly, not with higher-level functions like `fread(3)`.

Here is the revised code for POSIX, where the read function is a system call (syscall).

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Global variable to track number of interruptions
int interrupted_count = 0;

// Handler function for the signal
void signal_handler(int signum) {
    interrupted_count++;
    printf("Received signal %d, interrupted count: %d\n", signum, interrupted_count);
}

int main() {
    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open a file for reading
    int file = open("example.txt", O_RDONLY);
    if (file == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    char buffer[1024];

    while (1) {
        // Perform a blocking read
        ssize_t bytes_read = read(file, buffer, 1024);
        if (bytes_read == 0) {
            // End of file
            break;
        }

        if (bytes_read == -1) {
            if (errno == EINTR) {
                // Read interrupted by signal, retrying...
                printf("Read interrupted by signal, retrying...\n");
                continue;
            } else {
                // Handle other read errors
                perror("read");
                exit(EXIT_FAILURE);
            }
        }

        // Print the read data
        printf("%.*s", (int) bytes_read, buffer);
    }

    // Close the file
    close(file);

    return 0;
}
```

Note that in this revised code, we use the lower-level `open` and `read` system calls, which are POSIX-specific and do return EINTR when interrupted by a signal.

**Reading Network Packets from a Socket in C++**
======================================================

This example demonstrates how to read network packets from a socket on port 888 using C++ and the POSIX sockets API.

**Prerequisites**
---------------

*   C++ compiler (e.g., GCC)
*   POSIX sockets API (available on most Unix-like systems)

**Code**
-----

```cpp
#include <iostream>
#include <cstring>      // for memset
#include <sys/socket.h> // for socket, bind, listen, accept
#include <netinet/in.h> // for sockaddr_in
#include <unistd.h>     // for read, close
#include <arpa/inet.h>  // for inet_pton

int main() {
    // Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        std::cerr << "Error creating socket." << std::endl;
        return 1;
    }

    // Set address and port number for the socket
    sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(888);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    // Bind the socket to the address and port
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        std::cerr << "Error binding socket." << std::endl;
        close(sockfd);
        return 1;
    }

    // Listen for incoming connections
    if (listen(sockfd, 3) < 0) {
        std::cerr << "Error listening for connections." << std::endl;
        close(sockfd);
        return 1;
    }

    std::cout << "Server listening on port 888..." << std::endl;

    while (true) {
        // Accept an incoming connection
        sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            std::cerr << "Error accepting connection." << std::endl;
            continue;
        }

        std::cout << "Connection accepted from client IP address " << inet_ntoa(client_addr.sin_addr) << std::endl;

        char buffer[1024];
        int bytes_received;

        while ((bytes_received = read(client_fd, buffer, 1024)) > 0) {
            std::cout << "Received " << bytes_received << " bytes from client: ";
            for (int i = 0; i < bytes_received; ++i) {
                std::cout << std::hex << (int)buffer[i] << " ";
            }
            std::cout << std::dec << std::endl;
        }

        if (bytes_received < 0) {
            std::cerr << "Error reading from client socket." << std::endl;
        }

        close(client_fd);
    }

    close(sockfd);
    return 0;
}
```

**Explanation**
-------------

1.  We create a socket using the `socket` function, specifying the address family (`AF_INET` for IPv4) and the socket type (`SOCK_STREAM` for a connection-oriented socket).
2.  We set the address and port number for the socket using the `sockaddr_in` structure.
3.  We bind the socket to the address and port using the `bind` function.
4.  We listen for incoming connections using the `listen` function.
5.  We accept an incoming connection using the `accept` function, which returns a new file descriptor for the client socket.
6.  We read data from the client socket using the `read` function and print the received bytes in hexadecimal format.

**Example Use Case**
-------------------

To test this code, you can use a tool like `telnet` to connect to the server and send data:

1.  Compile and run the server code.
2.  Open a new terminal window and run the command `telnet 127.0.0.1 888`.
3.  Type some text and press Enter to send it to the server.
4.  The server should print the received bytes in hexadecimal format.

Note: This is a basic example and does not handle errors or disconnections robustly. In a real-world application, you would want to add error handling and potentially use a more robust networking library.

