**Computing the n-th Fibonacci Number Mod p**
=====================================================

Here's an efficient JavaScript function that uses matrix exponentiation to compute the n-th Fibonacci number modulo p.

### Code

```javascript
/**
 * Computes the n-th Fibonacci number modulo p.
 *
 * @param {number} n The index of the Fibonacci number to compute.
 * @param {number} p The modulo to apply to the result.
 * @returns {number} The n-th Fibonacci number modulo p.
 */
function fibonacciMod(n, p) {
  // Base cases
  if (n <= 1) {
    return n;
  }

  // Define the base matrix [[1, 1], [1, 0]]
  let baseMatrix = [
    [1, 1],
    [1, 0]
  ];

  // Compute the (n-1)-th power of the base matrix modulo p
  let resultMatrix = matrixPower(baseMatrix, n - 1, p);

  // The n-th Fibonacci number is the top-left element of the result matrix
  return resultMatrix[0][0];
}

/**
 * Computes the n-th power of a matrix modulo p.
 *
 * @param {number[][]} matrix The matrix to exponentiate.
 * @param {number} n The exponent.
 * @param {number} p The modulo to apply to the result.
 * @returns {number[][]} The n-th power of the matrix modulo p.
 */
function matrixPower(matrix, n, p) {
  // Base cases
  if (n === 0) {
    return [
      [1, 0],
      [0, 1]
    ];
  }

  if (n === 1) {
    return matrix;
  }

  // Compute the (n/2)-th power of the matrix modulo p
  let halfPower = matrixPower(matrix, Math.floor(n / 2), p);

  // Compute the n-th power of the matrix modulo p
  let result = matrixMultiply(halfPower, halfPower, p);

  if (n % 2 === 1) {
    result = matrixMultiply(result, matrix, p);
  }

  return result;
}

/**
 * Multiplies two matrices modulo p.
 *
 * @param {number[][]} a The first matrix.
 * @param {number[][]} b The second matrix.
 * @param {number} p The modulo to apply to the result.
 * @returns {number[][]} The product of the two matrices modulo p.
 */
function matrixMultiply(a, b, p) {
  let result = [
    [0, 0],
    [0, 0]
  ];

  for (let i = 0; i < 2; i++) {
    for (let j = 0; j < 2; j++) {
      for (let k = 0; k < 2; k++) {
        result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % p;
      }
    }
  }

  return result;
}
```

### Example Usage

```javascript
console.log(fibonacciMod(10, 100)); // Output: 55
```

This code uses matrix exponentiation to efficiently compute the n-th Fibonacci number modulo p. The `fibonacciMod` function takes two arguments, `n` and `p`, and returns the n-th Fibonacci number modulo p. The `matrixPower` function computes the n-th power of a matrix modulo p, and the `matrixMultiply` function multiplies two matrices modulo p.

Note that this implementation assumes that `n` and `p` are positive integers. If `n` or `p` can be negative or non-integer, additional error checking and handling will be necessary.

Below is a Python program implementing a simplified data storage oriented blockchain.

```python
import hashlib
import time
import random

class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.coins = 0
        self.hosted_data = {}

class Blockchain:
    def __init__(self):
        self.chain = []
        self.nodes = {}
        self.deposit_per_byte = 0.01
        self.deposit_per_block = 0.01
        self.fee_per_access = 0.01

    def add_node(self, node_id):
        self.nodes[node_id] = Node(node_id)

    def add_data(self, node_id, data, lifetime):
        data_hash = hashlib.sha256(data.encode()).hexdigest()
        data_size = len(data.encode())
        deposit_amount = data_size * self.deposit_per_byte + lifetime * self.deposit_per_block
        if self.nodes[node_id].coins >= deposit_amount:
            self.nodes[node_id].coins -= deposit_amount
            block = {
                'node_id': node_id,
                'data_hash': data_hash,
                'data_size': data_size,
                'lifetime': lifetime,
                'deposit_amount': deposit_amount,
                'timestamp': time.time()
            }
            self.chain.append(block)
            for node in self.nodes.values():
                node.hosted_data[data_hash] = block
            return True
        else:
            return False

    def distribute_deposit(self):
        for block in self.chain:
            if block['lifetime'] > 0:
                for node in self.nodes.values():
                    if block['data_hash'] in node.hosted_data:
                        node.coins += block['deposit_amount'] / len(self.nodes)
                block['lifetime'] -= 1

    def increase_deposit(self, node_id, data_hash, amount):
        for block in self.chain:
            if block['data_hash'] == data_hash:
                block['deposit_amount'] += amount
                block['lifetime'] += amount / self.deposit_per_block
                self.nodes[node_id].coins -= amount
                return True
        return False

    def access_data(self, node_id, data_hash):
        for block in self.chain:
            if block['data_hash'] == data_hash:
                for node in self.nodes.values():
                    if node.node_id != node_id and block['data_hash'] in node.hosted_data:
                        self.nodes[node_id].coins -= self.fee_per_access
                        node.coins += self.fee_per_access
                        return True
        return False

    def delete_data(self, node_id, data_hash):
        for block in self.chain:
            if block['data_hash'] == data_hash:
                for node in self.nodes.values():
                    if block['data_hash'] in node.hosted_data:
                        del node.hosted_data[block['data_hash']]
                self.chain.remove(block)
                self.nodes[node_id].coins += block['deposit_amount']
                return True
        return False

# Example usage
blockchain = Blockchain()
blockchain.add_node('node1')
blockchain.add_node('node2')
blockchain.nodes['node1'].coins = 100
blockchain.nodes['node2'].coins = 100

blockchain.add_data('node1', 'Hello, world!', 10)
print(blockchain.nodes['node1'].coins)  # 90
print(blockchain.nodes['node2'].coins)  # 100

blockchain.distribute_deposit()
print(blockchain.nodes['node1'].coins)  # 90.1
print(blockchain.nodes['node2'].coins)  # 100.1

blockchain.access_data('node2', hashlib.sha256('Hello, world!'.encode()).hexdigest())
print(blockchain.nodes['node1'].coins)  # 90.1
print(blockchain.nodes['node2'].coins)  # 99.1

blockchain.delete_data('node1', hashlib.sha256('Hello, world!'.encode()).hexdigest())
print(blockchain.nodes['node1'].coins)  # 100
print(blockchain.nodes['node2'].coins)  # 99.1
```

This code implements a simplified blockchain with two nodes. Node 1 adds some data to the blockchain and deposits coins, which are then distributed among both nodes. Node 2 accesses the data and pays a fee to Node 1. Finally, Node 1 deletes the data and receives its unused deposit back.

Please note that this is a very simplified example and does not include many features that a real-world blockchain would have, such as a consensus mechanism, security measures, or scalability solutions.

Here's a basic example of a voxel terrain engine in Godot using GDScript. This script will generate a 3D grid of voxels and allow the player to move around and place blocks.

**VoxelTerrain.gd**
```gdscript
extends Spatial

# Voxel grid dimensions
var grid_size = Vector3(16, 16, 16)

# Voxel size
var voxel_size = 1.0

# Voxel grid data
var voxels = {}

# Block types
enum BlockType { AIR, DIRT, GRASS, STONE }

func _ready():
    # Initialize voxel grid
    for x in range(grid_size.x):
        for y in range(grid_size.y):
            for z in range(grid_size.z):
                var voxel = get_voxel(x, y, z)
                voxels[Vector3(x, y, z)] = voxel

    # Create mesh for voxel grid
    create_mesh()

func get_voxel(x, y, z):
    # Simple noise function to generate terrain
    var noise = sin(x * 0.1) + sin(y * 0.1) + sin(z * 0.1)
    if noise > 0.5:
        return BlockType.DIRT
    elif noise > 0.2:
        return BlockType.GRASS
    elif y < 4:
        return BlockType.STONE
    else:
        return BlockType.AIR

func create_mesh():
    var mesh = Mesh.new()
    var surface_tool = SurfaceTool.new()

    # Loop through voxel grid and add triangles for visible voxels
    for x in range(grid_size.x):
        for y in range(grid_size.y):
            for z in range(grid_size.z):
                var voxel = voxels[Vector3(x, y, z)]
                if voxel != BlockType.AIR:
                    # Add triangles for each visible face
                    if x == 0 or voxels[Vector3(x - 1, y, z)] == BlockType.AIR:
                        add_face(surface_tool, x, y, z, Vector3(-1, 0, 0))
                    if x == grid_size.x - 1 or voxels[Vector3(x + 1, y, z)] == BlockType.AIR:
                        add_face(surface_tool, x, y, z, Vector3(1, 0, 0))
                    if y == 0 or voxels[Vector3(x, y - 1, z)] == BlockType.AIR:
                        add_face(surface_tool, x, y, z, Vector3(0, -1, 0))
                    if y == grid_size.y - 1 or voxels[Vector3(x, y + 1, z)] == BlockType.AIR:
                        add_face(surface_tool, x, y, z, Vector3(0, 1, 0))
                    if z == 0 or voxels[Vector3(x, y, z - 1)] == BlockType.AIR:
                        add_face(surface_tool, x, y, z, Vector3(0, 0, -1))
                    if z == grid_size.z - 1 or voxels[Vector3(x, y, z + 1)] == BlockType.AIR:
                        add_face(surface_tool, x, y, z, Vector3(0, 0, 1))

    # Commit surface tool to mesh
    surface_tool.commit_to_surface(mesh)

    # Create mesh instance and add to scene
    var mesh_instance = MeshInstance.new()
    mesh_instance.mesh = mesh
    add_child(mesh_instance)

func add_face(surface_tool, x, y, z, normal):
    surface_tool.begin(Mesh.PRIMITIVE_TRIANGLES)
    surface_tool.set_normal(normal)

    # Add vertices for face
    surface_tool.add_vertex(Vector3(x - 0.5, y - 0.5, z - 0.5) * voxel_size)
    surface_tool.add_vertex(Vector3(x + 0.5, y - 0.5, z - 0.5) * voxel_size)
    surface_tool.add_vertex(Vector3(x + 0.5, y + 0.5, z - 0.5) * voxel_size)

    surface_tool.add_vertex(Vector3(x - 0.5, y - 0.5, z - 0.5) * voxel_size)
    surface_tool.add_vertex(Vector3(x + 0.5, y + 0.5, z - 0.5) * voxel_size)
    surface_tool.add_vertex(Vector3(x - 0.5, y + 0.5, z - 0.5) * voxel_size)

    surface_tool.end()

func _input(event):
    if event is InputEventMouseButton and event.pressed:
        var ray = get_global_mouse_position()
        var voxel = get_voxel_from_ray(ray)
        if voxel:
            voxels[voxel] = BlockType.DIRT
            create_mesh()

func get_voxel_from_ray(ray):
    var origin = ray.origin
    var direction = ray.direction

    # Loop through voxel grid and find first voxel that intersects with ray
    for x in range(grid_size.x):
        for y in range(grid_size.y):
            for z in range(grid_size.z):
                var voxel = Vector3(x, y, z)
                var bounds = AABB(voxel - Vector3(0.5, 0.5, 0.5), Vector3(1, 1, 1))
                if bounds.intersects_ray(origin, direction):
                    return voxel
```
This script creates a 3D grid of voxels and generates a mesh for the visible voxels. It also allows the player to place blocks by clicking on the grid.

Please note that this is a very basic implementation and there's much room for optimization and improvement. For example, you might want to implement a more efficient algorithm for generating the mesh, or add support for different block types and textures.

Also, this script assumes that you have a `get_global_mouse_position()` function that returns the global position of the mouse cursor. You can implement this function by using the `get_global_mouse_position()` method of the `Input` class.

You can use this script by attaching it to a `Spatial` node in your scene, and then calling the `create_mesh()` function to generate the mesh.

