```ocaml
(* Load the necessary libraries *)
open GL3
open Bigarray

(* Define the compute shader source *)
let shader_source = "
#version 430 core

layout (local_size_x = 1, local_size_y = 1) in;

layout(std430, binding = 0) buffer Vector1
