"

(* Define a function to load a shader from a string *)
let load_shader shader_type source =
  let shader = glCreateShader shader_type in
  glShaderSource shader 1 [|source|] [|String.length source|];
  glCompileShader shader;
  let status = ref (0) in
  glGetShaderiv shader GL_COMPILE_STATUS status;
  if !status = 0 then
    let log = glGetShaderInfoLog shader in
    failwith log;
  shader

(* Define a function to create a compute program *)
