  let program = glCreateProgram () in
  glAttachShader program shader;
  glLinkProgram program;
  let status = ref (0) in
  glGetProgramiv program GL_LINK_STATUS status;
  if !status = 0 then
    let log = glGetProgramInfoLog program in
    failwith log;
  program

(* Define a function to perform a dot product using a compute shader *)
let dot_product vec1 vec2 =
  (* Create a compute shader *)
  let shader = load_shader GL_COMPUTE_SHADER shader_source in
  let program = create_compute_program shader in

  (* Create buffers for the vectors and result *)
  let vec1_buffer = glGenBuffer () in
  let vec2_buffer = glGenBuffer () in
  let result_buffer = glGenBuffer () in

  (* Initialize the buffers *)
  glBindBufferBase GL_SHADER_STORAGE_BUFFER 0 vec1_buffer;
  glBufferData GL_SHADER_STORAGE_BUFFER (sizeof_float * Array.length vec1) (bigarray_of_array1 (fun x -> x) vec1) GL_STATIC_DRAW;

  glBindBufferBase GL_SHADER_STORAGE_BUFFER 1 vec2_buffer;
  glBufferData GL_SHADER_STORAGE_BUFFER (sizeof_float * Array.length vec2) (bigarray_of_array1 (fun x -> x) vec2) GL_STATIC_DRAW;

  glBindBufferBase GL_SHADER_STORAGE_BUFFER 2 result_buffer;
  glBufferData GL_SHADER_STORAGE_BUFFER sizeof_float (bigarray_of_array1 (fun x -> 0.0) [|0.0|]) GL_STATIC_DRAW;

  (* Use the program and dispatch the compute shader *)
  glUseProgram program;
  glDispatchCompute 1 1 1;

  (* Get the result *)
  let result = ref (0.0) in
  glGetBufferSubData GL_SHADER_STORAGE_BUFFER 0 sizeof_float (bigarray_of_array1 (fun x -> !result) [|!result|]);
  !result

(* Test the dot product function *)
let () =
  let vec1 = [|1.0; 2.0; 3.0; 4.0|] in
  let vec2 = [|5.0; 6.0; 7.0; 8.0|] in
  let result = dot_product vec1 vec2 in
  Printf.printf "Dot product: %f\n" result
```

This code first loads the necessary OpenGL libraries and defines the compute shader source. It then defines functions to load a shader from a string, create a compute program, and perform a dot product using a compute shader. Finally, it tests the dot product function with two example vectors.

Note that this code assumes that the OpenGL context has been initialized and that the necessary libraries have been linked. You may need to modify the code to suit your specific use case.

Also, keep in mind that this is a very basic example. In a real-world application, you would likely want to handle errors more robustly, add more functionality, and optimize performance.

**Raycasting Shaders**
=======================

### Vertex Shader

The vertex shader is responsible for passing through the vertex positions and texture coordinates to the fragment shader. Since raycasting is done in the fragment shader, this vertex shader is relatively simple.

```glsl
#version 330 core

layout (location = 0) in vec3 aPos;
layout (location = 1) in vec2 aTexCoord;

out vec2 TexCoord;

void main()
{
    gl_Position = vec4(aPos, 1.0);
    TexCoord = aTexCoord;
}
```

### Fragment Shader

The fragment shader performs the actual raycasting. This implementation uses a simple 2D map to represent the world, where each pixel in the map corresponds to a cell in the world.

```glsl
#version 330 core

in vec2 TexCoord;

out vec4 FragColor;

uniform vec2 resolution; // Resolution of the screen
uniform vec2 playerPos;  // Position of the player
uniform vec2 playerDir;  // Direction of the player
uniform sampler2D mapTexture; // Texture containing the 2D map
uniform float fov; // Field of view
uniform float mapSize; // Size of the map

void main()
{
    // Calculate the ray direction
    vec2 rayDir = normalize(vec2(
        (TexCoord.x - 0.5) * resolution.x / resolution.y,
        -1.0
    ) * fov);

    // Rotate the ray direction by the player's direction
    rayDir = vec2(
        rayDir.x * playerDir.x - rayDir.y * playerDir.y,
        rayDir.x * playerDir.y + rayDir.y * playerDir.x
    );

    // Initialize the distance to the wall
    float dist = 0.0;

    // Loop until we hit a wall
    while (dist < 100.0) {
        // Calculate the current position of the ray
        vec2 pos = playerPos + rayDir * dist;

        // Check if we're outside the map
        if (pos.x < 0.0 || pos.x > mapSize || pos.y < 0.0 || pos.y > mapSize) {
            break;
        }

        // Check if we hit a wall
        vec4 mapColor = texture(mapTexture, pos / mapSize);
        if (mapColor.r > 0.5) {
            break;
        }

        // Increase the distance
        dist += 0.1;
    }

    // Calculate the color of the wall based on the distance
    float color = 1.0 / (1.0 + dist * dist * 0.1);

    // Output the final color
    FragColor = vec4(color, color, color, 1.0);
}
```

### Example Use Case

To use these shaders, you would:

1. Create a vertex buffer object (VBO) and an index buffer object (IBO) to store the vertices and indices of a quad that covers the entire screen.
2. Create a texture to store the 2D map.
3. Create a shader program using the vertex and fragment shaders above.
4. Set the uniforms `resolution`, `playerPos`, `playerDir`, `mapTexture`, `fov`, and `mapSize` to the correct values.
5. Draw the quad using the shader program.

Note that this is a simplified example and you may need to modify the shaders to fit your specific use case. Additionally, this implementation does not handle things like texture mapping, lighting, or collision detection, which you may want to add depending on your specific needs.

**Reading a CSV File in JavaScript**
=====================================

JavaScript is typically used for client-side scripting on the web, but with the help of Node.js, we can also use it for server-side scripting and file operations. Here's an example of how to read a CSV file in JavaScript using Node.js.

**Install the Required Packages**
-----------------------------

First, you'll need to install the `fs` (File System) and `csv-parser` packages. The `fs` package is a built-in Node.js package, so you only need to install `csv-parser`. Run the following command in your terminal:

```bash
npm install csv-parser
```

**Code**
-----

Create a new JavaScript file (e.g., `readCSV.js`) and add the following code:

```javascript
// Import the required packages
const fs = require('fs');
const csv = require('csv-parser');

// Function to read the CSV file
function readCSV(filePath) {
  // Create an empty array to store the CSV data
  let csvData = [];

  // Read the CSV file
  fs.createReadStream(filePath)
    .pipe(csv())
    .on('data', (data) => {
      // Add each row to the csvData array
      csvData.push(data);
    })
    .on('end', () => {
      // Log the CSV data
      console.log(csvData);
    })
    .on('error', (error) => {
      // Log any errors
      console.error(error);
    });
}

// Call the readCSV function with the file path
readCSV('example.csv');
```

**Explanation**
-------------

Here's what each part of the code does:

1. **Importing Packages**: We import the `fs` and `csv-parser` packages using the `require` function.
2. **readCSV Function**: We define a function `readCSV` that takes the file path as an argument.
3. **Creating an Empty Array**: We create an empty array `csvData` to store the CSV data.
4. **Reading the CSV File**: We use the `fs.createReadStream` method to create a readable stream from the CSV file. We then pipe this stream to the `csv()` function, which parses the CSV data.
5. **Processing the CSV Data**: We use the `on` method to attach event listeners to the stream. The `data` event is emitted for each row in the CSV file, and we add each row to the `csvData` array. The `end` event is emitted when the stream is finished, and we log the `csvData` array. The `error` event is emitted if there's an error, and we log the error.
6. **Calling the readCSV Function**: We call the `readCSV` function with the file path as an argument.

**Example Use Case**
--------------------

Suppose you have a CSV file named `example.csv` with the following contents:

```csv
Name,Age,Country
John,25,USA
Jane,30,Canada
Bob,35,UK
```

When you run the `readCSV` function with the file path `example.csv`, it will log the following output:

```json
[
  { Name: 'John', Age: '25', Country: 'USA' },
  { Name: 'Jane', Age: '30', Country: 'Canada' },
  { Name: 'Bob', Age: '35', Country: 'UK' }
]
```

This is the CSV data parsed into a JavaScript array of objects.

**Extracting Text from a Document using JavaScript**
======================================================

Below is a simple JavaScript function that extracts the text from a document. This function works by recursively traversing the DOM and collecting the text content of each element.

```javascript
/**
 * Extracts the text from a document.
 *
 * @param {Document} document - The document to extract text from.
 * @returns {string} The extracted text.
 */
function extractTextFromDocument(document) {
  // Create a function to recursively traverse the DOM and collect text content
  function collectText(element) {
    let text = '';

    // If the element is a text node, add its text content to the collection
    if (element.nodeType === 3) {
      text += element.nodeValue;
    }

    // If the element has child nodes, recursively collect their text content
    if (element.hasChildNodes()) {
      for (let child of element.childNodes) {
        text += collectText(child);
      }
    }

    return text;
  }

  // Start the recursive traversal at the document body
  return collectText(document.body);
}

// Example usage:
const text = extractTextFromDocument(document);
console.log(text);
```

This function uses a recursive approach to traverse the DOM and collect the text content of each element. It handles both text nodes and elements with child nodes.

**Note:** This function extracts all text from the document, including text that may not be visible on the page (e.g., text within `script` or `style` elements). If you only want to extract visible text, you'll need to modify the function to filter out non-visible elements.

**Alternative Approach using `document.body.textContent`**
--------------------------------------------------------

If you don't need to support older browsers, you can use the `textContent` property of the `document.body` element to extract the text from the document in a single line of code:

```javascript
const text = document.body.textContent;
console.log(text);
```

This approach is simpler and more efficient than the recursive function above, but it may not work in older browsers that don't support the `textContent` property.

Here's a Java method using Stream API to check if a list has not more than one entry:

```java
import java.util.List;
import java.util.Optional;

public class Main {

    public static <T> T getSingleElement(List<T> list) {
        return list.stream()
                .reduce((a, b) -> {
                    throw new RuntimeException("More than one element found in the list");
                })
                .orElse(null);
    }

    public static void main(String[] args) {
        List<String> list1 = List.of("one");
        List<String> list2 = List.of("one", "two");
        List<String> list3 = List.of();

        System.out.println(getSingleElement(list1)); // prints: one
        try {
            System.out.println(getSingleElement(list2)); // throws RuntimeException
        } catch (RuntimeException e) {
            System.out.println(e.getMessage()); // prints: More than one element found in the list
        }
        System.out.println(getSingleElement(list3)); // prints: null
    }
}
```

This method uses the `reduce()` function of the Stream API to check the size of the list. If there is more than one element in the list, `reduce()` applies a lambda expression to the first two elements, which throws an exception in this case. If the list is empty, `reduce()` returns an empty `Optional`, and the `orElse(null)` call returns `null`. If the list contains exactly one element, `reduce()` does not apply the lambda expression and directly returns an `Optional` containing the element, which is then returned by the `orElse(null)` call.

Here's a simple implementation of a Kalman filter in GNU Octave:

```octave
function [x, P] = kalman_filter(x_prev, P_prev, F, Q, z, H, R)
  % Predict
  x_pred = F * x_prev;
  P_pred = F * P_prev * F' + Q;

  % Update
  K = P_pred * H' / (H * P_pred * H' + R);
  x = x_pred + K * (z - H * x_pred);
  P = (eye(size(P_pred)) - K * H) * P_pred;
endfunction

% Example usage:
% Define the system and measurement models
F = [1 1; 0 1];  % State transition matrix
Q = 0.1 * eye(2);  % Process noise covariance
H = [1 0];  % Measurement matrix
R = 1;  % Measurement noise covariance

% Initialize the state and covariance
x = [0; 0];  % Initial state
P = eye(2);  % Initial covariance

% Generate some measurements
z = [1; 2; 3; 4; 5];

% Apply the Kalman filter to each measurement
for i = 1:length(z)
  [x, P] = kalman_filter(x, P, F, Q, z(i), H, R);
  printf("State at time %d: x = [%f; %f]\n", i, x(1), x(2));
endfor
```

This code defines a function `kalman_filter` that takes the previous state `x_prev` and covariance `P_prev`, the state transition matrix `F`, the process noise covariance `Q`, the measurement `z`, the measurement matrix `H`, and the measurement noise covariance `R` as inputs. It then computes the predicted state and covariance using the system model and updates the state and covariance using the measurement.

The example usage demonstrates how to apply the Kalman filter to a simple system with one measurement. You can modify the system and measurement models, the initial state and covariance, and the measurements to suit your specific application.

Please note that this is a simplified example and might need to be adapted to fit the needs of your specific application. Also, the performance of the Kalman filter can be sensitive to the choice of the process and measurement noise covariances, so you may need to adjust these parameters to achieve good results.

