#include "reverb.h"

Reverb::Reverb(int sampleRate, int framesPerBuffer) {
    // Initialize reverb parameters
    roomSize_ = 0.5f;
    damping_ = 0.5f;
    wetLevel_ = 0.5f;
    dryLevel_ = 0.5f;
    width_ = 1.0f;
    mode_ = 0;
}

Reverb::~Reverb() {}

void Reverb::process(float* input, float* output, int numSamples) {
    // Simple reverb algorithm
    for (int i = 0; i < numSamples; i++) {
        float drySignal = input[i] * dryLevel_;
        float wetSignal = input[i] * wetLevel_;

        // Add delay to wet signal
        int delay = (int)(roomSize_ * 10000);
        if (i - delay >= 0) {
            wetSignal += output[i - delay] * damping_;
        }

        // Mix dry and wet signals
        output[i] = drySignal + wetSignal;
    }
}

void Reverb::setRoomSize(float roomSize) {
    roomSize_ = roomSize;
}

void Reverb::setDamping(float damping) {
    damping_ = damping;
}

