            val inputBuffer = FloatArray(bufferSize / 4)
            val outputBuffer = FloatArray(bufferSize / 4)

            while (true) {
                audioRecord?.read(inputBuffer, 0, inputBuffer.size, AudioRecord.READ_BLOCKING)

                reverbEffect.process(inputBuffer, outputBuffer, inputBuffer.size)

                audioTrack?.write(outputBuffer, 0, outputBuffer.size, AudioTrack.WRITE_BLOCKING)
            }
