Here is an example of how to create a local VPN service in Android using Kotlin that can filter packets by destination IP address. This example uses the `VpnService` class provided by Android to create a local VPN and intercept network traffic.

**VpnService Class**
```kotlin
import android.app.PendingIntent
import android.net.VpnService
import android.os.ParcelFileDescriptor
import java.io.FileInputStream
import java.io.FileOutputStream
import java.net.InetAddress
import java.net.UnknownHostException

class LocalVpnService : VpnService() {

    private var vpnInterface: ParcelFileDescriptor? = null
    private var vpnThread: Thread? = null

    override fun onStartCommand(intent: Intent, flags: Int, startId: Int): Int {
        // Create the VPN interface
        vpnInterface = establish()
        if (vpnInterface != null) {
            // Start the VPN thread
            vpnThread = Thread(VpnRunnable(vpnInterface!!))
            vpnThread!!.start()
        }
        return super.onStartCommand(intent, flags, startId)
    }

    override fun onDestroy() {
        super.onDestroy()
        // Stop the VPN thread
        vpnThread?.interrupt()
        vpnThread = null
        // Close the VPN interface
        vpnInterface?.close()
        vpnInterface = null
    }

    private fun establish(): ParcelFileDescriptor? {
        val builder = Builder()
        builder.setSession("LocalVpnService")
        builder.addAddress("10.0.0.2", 32)
        builder.addRoute("0.0.0.0", 0)
        builder.addDnsServer("8.8.8.8")
        return builder.establish()
    }

    private inner class VpnRunnable(private val vpnInterface: ParcelFileDescriptor) : Runnable {

        override fun run() {
            val vpnInputStream = FileInputStream(vpnInterface.fileDescriptor)
            val vpnOutputStream = FileOutputStream(vpnInterface.fileDescriptor)

            while (!Thread.currentThread().isInterrupted()) {
                val packet = ByteArray(4096)
                val bytesRead = vpnInputStream.read(packet)
                if (bytesRead > 0) {
                    // Filter packets by destination IP address
                    if (filterPacket(packet)) {
                        vpnOutputStream.write(packet, 0, bytesRead)
                    }
                }
            }
        }

        private fun filterPacket(packet: ByteArray): Boolean {
            // Get the destination IP address from the packet
            val destIp = getDestinationIp(packet)
            if (destIp != null) {
                // Filter packets by destination IP address
                if (destIp.hostAddress == "192.168.1.100") {
                    // Drop packets to this IP address
                    return false
                }
            }
            return true
        }

        private fun getDestinationIp(packet: ByteArray): InetAddress? {
            // Get the destination IP address from the packet
            // This assumes an IPv4 packet
            if (packet[0].toInt() == 0x45) {
                val destIp = ByteArray(4)
                destIp[0] = packet[16]
                destIp[1] = packet[17]
                destIp[2] = packet[18]
                destIp[3] = packet[19]
                try {
                    return InetAddress.getByAddress(destIp)
                } catch (e: UnknownHostException) {
                    // Handle exception
                }
            }
            return null
        }
    }
}
```

