use App\Models\Favorite;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    const SESSION_KEY = 'favorites';

    private function getFavorites(): array
    {
        if (auth()->check()) {
            return auth()->user()->favorites()->pluck('name')->toArray();
        }

        return Session::get(self::SESSION_KEY, []);
    }

    private function saveFavorites(array $favorites): void
    {
        if (auth()->check()) {
            auth()->user()->favorites()->delete();
            foreach ($favorites as $favorite) {
                auth()->user()->favorites()->create(['name' => $favorite]);
            }
        } else {
            Session::put(self::SESSION_KEY, $favorites);
        }
    }

    public function addFavorite(string $name): void
    {
        $favorites = $this->getFavorites();

        if (!in_array($name, $favorites)) {
            $favorites[] = $name;
            $this->saveFavorites($favorites);
        }
    }

    public function removeFavorite(string $name): void
    {
        $favorites = $this->getFavorites();

        if (($key = array_search($name, $favorites)) !== false) {
            unset($favorites[$key]);
            $this->saveFavorites(array_values($favorites));
        }
    }

    public function getFavoritesList(): array
