**Gaussian Blur Metal Compute Kernel**

Below is an example of a Metal compute kernel that performs a Gaussian blur on an image.

```metal
#include <metal_stdlib>
using namespace metal;

// Structure to hold Gaussian blur parameters
struct GaussianBlurParams {
    float sigma;
    int radius;
};

// Kernel function to perform Gaussian blur
kernel void gaussianBlur(
    texture2d<float, access::read> inTexture [[texture(0)]],
    texture2d<float, access::write> outTexture [[texture(1)]],
    constant GaussianBlurParams &params [[buffer(0)]],
    uint2 gid [[thread_position_in_grid]])
{
    // Check if the current thread is within the bounds of the texture
    if (gid.x >= outTexture.get_width() || gid.y >= outTexture.get_height()) {
        return;
    }

    // Initialize the output pixel color
    float4 outputColor = float4(0.0);

    // Calculate the total weight of the Gaussian distribution
    float totalWeight = 0.0;

    // Iterate over the neighboring pixels within the blur radius
    for (int x = -params.radius; x <= params.radius; x++) {
        for (int y = -params.radius; y <= params.radius; y++) {
            // Calculate the distance from the center pixel
            float distanceSquared = float(x * x + y * y);

            // Calculate the Gaussian weight for the current pixel
            float weight = exp(-distanceSquared / (2.0 * params.sigma * params.sigma));

            // Check if the current pixel is within the bounds of the texture
            if (gid.x + x >= 0 && gid.x + x < inTexture.get_width() &&
                gid.y + y >= 0 && gid.y + y < inTexture.get_height()) {
                // Sample the input texture at the current pixel position
                float4 sampleColor = inTexture.read(uint2(gid.x + x, gid.y + y));

                // Accumulate the weighted color value
                outputColor += sampleColor * weight;

                // Accumulate the total weight
                totalWeight += weight;
            }
        }
    }

    // Normalize the output color by the total weight
    outputColor /= totalWeight;

    // Write the blurred pixel color to the output texture
    outTexture.write(outputColor, gid);
}
```

