import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [tasks, setTasks] = useState([]);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [completed, setCompleted] = useState(false);

  useEffect(() => {
    axios.get('http://localhost:3001/tasks')
      .then(response => {
        setTasks(response.data);
      })
      .catch(error => {
        console.error(error);
      });
  }, []);

  const handleSubmit = (event) => {
    event.preventDefault();
    const newTask = { title, description, completed };
    axios.post('http://localhost:3001/tasks', newTask)
      .then(response => {
        setTasks([...tasks, response.data]);
        setTitle('');
        setDescription('');
        setCompleted(false);
      })
      .catch(error => {
        console.error(error);
      });
  };

  const handleUpdate = (task) => {
    axios.put(`http://localhost:3001/tasks/${task.id}`, task)
      .then(response => {
        setTasks(tasks.map((t) => t.id === task.id ? response.data : t));
      })
      .catch(error => {
        console.error(error);
      });
  };

  const handleDelete = (task) => {
    axios.delete(`http://localhost:3001/tasks/${task.id}`)
      .then(() => {
        setTasks(tasks.filter((t) => t.id !== task.id));
      })
      .catch(error => {
        console.error(error);
      });
  };

  return (
    <div>
      <h1>To-Do List</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          placeholder="Title"
        />
        <input
          type="text"
          value={description}
          onChange={(event) => setDescription(event.target.value)}
          placeholder="Description"
        />
        <input
          type="checkbox"
          checked={completed}
          onChange={(event) => setCompleted(event.target.checked)}
        />
        <button type="submit">Add Task</button>
      </form>
      <ul>
        {tasks.map((task) => (
          <li key={task.id}>
            <input
              type="checkbox"
              checked={task.completed}
              onChange={() => handleUpdate({ ...task, completed: !task.completed })}
            />
            <span style={{ textDecoration: task.completed ? 'line-through' : 'none' }}>
              {task.title} - {task.description}
            </span>
            <button onClick={() => handleDelete(task)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

**Usage**
-----

1. Create a new PostgreSQL database and add the `tasks` table.
2. Create a new Node.js project and install the required dependencies.
3. Create a new file `server.js` and copy the backend code into it.
4. Create a new React project and install the required dependencies.
5. Create a new file `App.js` and copy the frontend code into it.
6. Start the backend server by running `node server.js`.
7. Start the frontend development server by running `npm start`.
8. Open your web browser and navigate to `http://localhost:3000`.

Note: This is a basic implementation and you should consider adding authentication and authorization to your application in a real-world scenario.

**Greatest Common Divisor (GCD) Calculator in Java**
=====================================================

Below is a simple Java program that prompts the user to enter two positive integers and displays their greatest common divisor (GCD).

### Code
```java
import java.util.InputMismatchException;
import java.util.Scanner;

public class GCD {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int num1 = getPositiveIntegerInput(scanner, "Enter the first positive integer: ");
        int num2 = getPositiveIntegerInput(scanner, "Enter the second positive integer: ");

        int gcd = calculateGCD(num1, num2);

        System.out.println("The greatest common divisor of " + num1 + " and " + num2 + " is: " + gcd);
    }

    /**
     * Prompts the user to enter a positive integer and handles invalid input.
     *
     * @param scanner the Scanner object to read user input
     * @param prompt  the prompt to display to the user
     * @return the positive integer entered by the user
     */
    private static int getPositiveIntegerInput(Scanner scanner, String prompt) {
        while (true) {
            try {
                System.out.print(prompt);
                int input = scanner.nextInt();

                if (input <= 0) {
                    System.out.println("Please enter a positive integer.");
                } else {
                    return input;
                }
            } catch (InputMismatchException e) {
                System.out.println("Invalid input. Please enter a positive integer.");
                scanner.next(); // Consume the invalid input
            }
        }
    }

    /**
     * Calculates the greatest common divisor (GCD) of two numbers using the Euclidean algorithm.
     *
     * @param num1 the first number
     * @param num2 the second number
     * @return the greatest common divisor of num1 and num2
     */
    private static int calculateGCD(int num1, int num2) {
        while (num2 != 0) {
            int temp = num1;
            num1 = num2;
            num2 = temp % num2;
        }
        return num1;
    }
}
```

### How it works

1. The program uses a `Scanner` object to read user input.
2. The `getPositiveIntegerInput` method prompts the user to enter a positive integer and handles invalid input (e.g., non-integer values or negative numbers).
3. The `calculateGCD` method uses the Euclidean algorithm to calculate the greatest common divisor of two numbers.
4. The program displays the GCD of the two input numbers.

### Example Use Cases

* Enter `12` and `18` to calculate their GCD, which is `6`.
* Enter `24` and `30` to calculate their GCD, which is `6`.
* Enter `48` and `18` to calculate their GCD, which is `6`.

