**JavaScript**
-------------

```javascript
// sprite-editor.js

class SpriteEditor {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.drawing = false;
    this.lastX = 0;
    this.lastY = 0;
    this.color = '#000000';

    // Bind events
    canvas.addEventListener('mousedown', this.startDrawing.bind(this));
    canvas.addEventListener('mousemove', this.draw.bind(this));
    canvas.addEventListener('mouseup', this.stopDrawing.bind(this));

    // Get save and clear buttons
    const saveBtn = document.getElementById('save-btn');
    const clearBtn = document.getElementById('clear-btn');
    const colorPicker = document.getElementById('color-picker');

    // Bind save and clear events
    saveBtn.addEventListener('click', this.saveSprite.bind(this));
    clearBtn.addEventListener('click', this.clearCanvas.bind(this));
    colorPicker.addEventListener('input', this.updateColor.bind(this));
  }

  // Start drawing when mouse is pressed
  startDrawing(e) {
    this.drawing = true;
    this.lastX = e.offsetX;
    this.lastY = e.offsetY;
  }

  // Draw when mouse is moved while pressed
  draw(e) {
    if (this.drawing) {
      this.ctx.strokeStyle = this.color;
      this.ctx.lineWidth = 5;
      this.ctx.lineCap = 'round';
      this.ctx.lineJoin = 'round';

      this.ctx.beginPath();
      this.ctx.moveTo(this.lastX, this.lastY);
      this.ctx.lineTo(e.offsetX, e.offsetY);
      this.ctx.stroke();

      this.lastX = e.offsetX;
      this.lastY = e.offsetY;
    }
  }

  // Stop drawing when mouse is released
  stopDrawing() {
    this.drawing = false;
  }

  // Save sprite as PNG image
  saveSprite() {
    const link = document.createElement('a');
    link.href = this.canvas.toDataURL();
    link.download = 'sprite.png';
    link.click();
  }

  // Clear canvas
  clearCanvas() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  }

  // Update drawing color
  updateColor(e) {
    this.color = e.target.value;
  }
}

// Initialize sprite editor
const canvas = document.getElementById('canvas');
const spriteEditor = new SpriteEditor(canvas);
```

**Example Use Cases**
---------------------

1.  Create a new sprite: Open the editor and start drawing using your mouse or touchpad.
