4.  Clear the canvas: Click the "Clear" button to erase the entire canvas and start anew.
5.  Change the drawing color: Use the color picker input to select a new color for drawing.

To implement the Action class, we can use a data-driven approach where the actions are defined in a configuration file. We can use a simple DSL (Domain Specific Language) to define the actions.

Here's an example implementation in Python:

```python
import json

class Action:
    def __init__(self, action_data):
        self.name = action_data["name"]
        self.type = action_data["type"]
        self.params = action_data["params"]
        self.operations = {
            "deal_damage": self.deal_damage,
            "heal": self.heal,
            "calculate_damage": self.calculate_damage,
            "calculate_heal": self.calculate_heal,
        }

    def perform(self, actor, target):
        for operation in self.params["operations"]:
            op_type = operation["type"]
            if op_type in self.operations:
                self.operations[op_type](actor, target, operation["params"])
            else:
                raise ValueError(f"Unknown operation type: {op_type}")

    def deal_damage(self, actor, target, params):
        damage = self.calculate_damage(actor, target, params)
        target.hp -= damage
        print(f"{actor.name} deals {damage} damage to {target.name}")

    def heal(self, actor, target, params):
        heal_amount = self.calculate_heal(actor, target, params)
        target.hp += heal_amount
        print(f"{actor.name} heals {target.name} for {heal_amount}")

    def calculate_damage(self, actor, target, params):
        if "base_damage" in params:
            return params["base_damage"]
        elif "damage_percentage" in params:
            if params["damage_percentage"]["of"] == "target_hp":
                return target.hp * params["damage_percentage"]["value"]
            elif params["damage_percentage"]["of"] == "actor_hp":
                return actor.hp * params["damage_percentage"]["value"]
                actor.hp -= actor.hp * params["actor_damage"]["value"]
        else:
            raise ValueError("Invalid damage calculation parameters")

    def calculate_heal(self, actor, target, params):
        if "base_heal" in params:
            return params["base_heal"]
        elif "heal_percentage" in params:
