const express = require('express');
const app = express();

// Define a middleware function to map domains to tenants
app.use((req, res, next) => {
    const domain = req.headers.host;
    const tenant = getTenantFromDomain(domain);
    req.tenant = tenant;
    next();
});

// Define a function to get the tenant from the domain
