            compact()
            regular()
            expanded()
        }
    ) { measurables, constraints ->
        val compactMeasurable = measurables[0]
        val regularMeasurable = measurables[1]
        val expandedMeasurable = measurables[2]

        val width = constraints.maxWidth
        val height = constraints.maxHeight

        // Determine which content to show based on the available space
        val contentToMeasure = when {
            width < 300.dp -> compactMeasurable
            width < 600.dp -> regularMeasurable
            else -> expandedMeasurable
        }

        // Measure the selected content
        val placeable = contentToMeasure.measure(constraints)

        // Position the selected content
        layout(width, height) {
            placeable.place(0, 0)
        }
    }
}
```
In this example, the `ResponsiveContainer` composable takes three child composables: `compact`, `regular`, and `expanded`. It uses the `Layout` API to measure and position these children based on the available space.

When the available space is narrow (less than 300dp), it shows the `compact` content. When the available space is medium (between 300dp and 600dp), it shows the `regular` content. When the available space is wide (more than 600dp), it shows the `expanded` content.

You can use this composable like this:
```kotlin
@Composable
fun MyScreen() {
    ResponsiveContainer {
        compact = { Text("Compact content") }
        regular = { Text("Regular content") }
        expanded = { Text("Expanded content") }
    }
}
```
This will show the compact content when the screen is narrow, the regular content when the screen is medium, and the expanded content when the screen is wide.

Note that this is a simplified example, and you can customize the logic to determine which content to show based on the available space. You can also add more child composables or modify the layout to position the children in different ways.

Also, you can use `BoxWithConstraints` composable to make it easier to work with the available space.
```kotlin
@Composable
fun ResponsiveContainer(
    modifier: Modifier = Modifier,
    compact: @Composable () -> Unit,
    regular: @Composable () -> Unit,
    expanded: @Composable () -> Unit
) {
    BoxWithConstraints(modifier = modifier) {
        if (maxWidth < 300.dp) {
            compact()
        } else if (maxWidth < 600.dp) {
            regular()
        } else {
            expanded()
        }
    }
}
```
This will achieve the same result as the previous example, but it's easier to read and write.
